def generate(seed):
    r = random.Random(seed)
    if r.random() < 0.35:
        return str(r.choice([61, 73, 94, 97, 106, 109, 113, 124,
                             127, 133, 137, 139, 149, 151, 157]))
    while True:
        d = r.randrange(2, 160)
        s = int(d ** 0.5)
        while (s + 1) * (s + 1) <= d:
            s += 1
        if s * s != d:
            return str(d)

