def solve(clue):
    D = int(clue)
    a0 = int(D ** 0.5)
    while (a0 + 1) * (a0 + 1) <= D:
        a0 += 1
    while a0 * a0 > D:
        a0 -= 1
    m, d, a = 0, 1, a0
    n1, n2 = 1, a0
    d1, d2 = 0, 1
    for _ in range(10000):
        if n2 * n2 - D * d2 * d2 == 1:
            return str(n2) + ' ' + str(d2)
        m = d * a - m
        d = (D - m * m) // d
        a = (a0 + m) // d
        n1, n2 = n2, a * n2 + n1
        d1, d2 = d2, a * d2 + d1
    return ''

